(function () {
  "use strict";

  const prefersReducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const $ = (selector, parent = document) => parent.querySelector(selector);
  const $$ = (selector, parent = document) => Array.from(parent.querySelectorAll(selector));
  const EMBEDDED_PHOTOS = {
    "assets/photo1.jpg": "data:image/jpeg;base64,",
    "assets/photo2.jpg": "data:image/jpeg;base64,",
  };

  const body = document.body;
  const burstLayer = $(".burst-layer");
  const header = $(".site-header");
  const navToggle = $(".nav-toggle");
  const backToTop = $(".back-to-top");
  const lightboxDialog = $("#lightboxDialog");
  const lightboxImage = $("#lightboxImage");
  const lightboxCaption = $("#lightboxCaption");
  const secretDialog = $("#secretDialog");
  const surpriseOverlay = $("#surpriseOverlay");

  body.classList.add("loading");

  function hideLoader() {
    const loader = $(".loading-screen");
    if (!loader) return;
    loader.classList.add("is-hidden");
    body.classList.remove("loading");
    window.setTimeout(() => loader.remove(), prefersReducedMotion ? 20 : 750);
  }

  window.setTimeout(hideLoader, prefersReducedMotion ? 700 : 2600);

  function initializeImages() {
    $$("img[data-src]").forEach((image) => {
      const src = image.dataset.src;
      const holder = image.closest(".photo-card, .memory-thumb");
      if (!src) return;

      const applyLoadedSource = (resolvedSrc) => {
        image.src = resolvedSrc;
        image.hidden = false;
        image.removeAttribute("data-src");
        holder?.classList.add("has-photo");
        holder?.classList.remove("missing-photo");
        if (holder) holder.dataset.photoReady = "true";
      };

      const probe = new Image();
      probe.onload = () => {
        applyLoadedSource(src);
      };
      probe.onerror = () => {
        const embeddedSrc = EMBEDDED_PHOTOS[src];
        if (embeddedSrc) {
          applyLoadedSource(embeddedSrc);
        } else {
          image.hidden = true;
          image.removeAttribute("data-src");
          holder?.classList.add("missing-photo");
          if (holder) holder.dataset.photoReady = "false";
        }
      };
      probe.src = src;
    });
  }

  function revealOnScroll() {
    const revealItems = $$(".reveal");
    if (prefersReducedMotion || !("IntersectionObserver" in window)) {
      revealItems.forEach((item) => item.classList.add("is-visible"));
      return;
    }

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add("is-visible");
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.16, rootMargin: "0px 0px -8% 0px" });

    revealItems.forEach((item) => observer.observe(item));
  }

  function emitConfetti(target, options = {}) {
    if (!burstLayer) return;

    const count = prefersReducedMotion ? 10 : (options.count || 38);
    const symbols = options.symbols || ["â¤", "â™¡", "âœ¦", "âœ§", "â‹"];
    const rect = target && target.getBoundingClientRect
      ? target.getBoundingClientRect()
      : { left: window.innerWidth / 2, top: window.innerHeight / 2, width: 0, height: 0 };
    const originX = rect.left + rect.width / 2;
    const originY = rect.top + rect.height / 2;

    for (let index = 0; index < count; index += 1) {
      const particle = document.createElement("span");
      const angle = Math.random() * Math.PI * 2;
      const distance = 70 + Math.random() * (options.spread || 170);
      const dx = Math.cos(angle) * distance;
      const dy = Math.sin(angle) * distance - Math.random() * 80;

      particle.className = "confetti-particle";
      particle.textContent = symbols[Math.floor(Math.random() * symbols.length)];
      particle.style.setProperty("--x", `${originX}px`);
      particle.style.setProperty("--y", `${originY}px`);
      particle.style.setProperty("--dx", `${dx}px`);
      particle.style.setProperty("--dy", `${dy}px`);
      particle.style.setProperty("--rot", `${Math.random() * 720 - 360}deg`);
      particle.style.setProperty("--size", `${0.9 + Math.random() * 1.1}rem`);
      particle.style.setProperty("--duration", `${prefersReducedMotion ? 550 : 950 + Math.random() * 520}ms`);
      burstLayer.appendChild(particle);
      window.setTimeout(() => particle.remove(), prefersReducedMotion ? 700 : 1700);
    }
  }

  function scrollToSection(selector) {
    const section = $(selector);
    if (!section) return;
    section.scrollIntoView({ behavior: prefersReducedMotion ? "auto" : "smooth", block: "start" });
  }

  function setupNavigation() {
    if (!navToggle || !header) return;

    navToggle.addEventListener("click", () => {
      const isOpen = header.classList.toggle("nav-open");
      navToggle.setAttribute("aria-expanded", String(isOpen));
      navToggle.setAttribute("aria-label", isOpen ? "Close navigation" : "Open navigation");
    });

    $$(".site-nav a").forEach((link) => {
      link.addEventListener("click", () => {
        header.classList.remove("nav-open");
        navToggle.setAttribute("aria-expanded", "false");
        navToggle.setAttribute("aria-label", "Open navigation");
      });
    });
  }

  function setupBackToTop() {
    if (!backToTop) return;

    const toggleButton = () => {
      backToTop.classList.toggle("is-visible", window.scrollY > 520);
    };

    toggleButton();
    window.addEventListener("scroll", toggleButton, { passive: true });
    backToTop.addEventListener("click", () => scrollToSection("#hero"));
  }

  function setupSurpriseButtons() {
    const openSurprise = $("#openSurprise");
    const finalSurprise = $("#finalSurprise");
    const closeOverlay = $("#closeOverlay");

    openSurprise?.addEventListener("click", () => {
      emitConfetti(openSurprise, { count: 42, spread: 135 });
      scrollToSection("#photos");
    });

    finalSurprise?.addEventListener("click", () => {
      surpriseOverlay?.classList.add("is-visible");
      surpriseOverlay?.setAttribute("aria-hidden", "false");
      emitConfetti(finalSurprise, { count: 110, spread: 290, symbols: ["â¤", "â™¡", "âœ¨", "âœ¦", "â‹"] });
    });

    closeOverlay?.addEventListener("click", () => {
      surpriseOverlay?.classList.remove("is-visible");
      surpriseOverlay?.setAttribute("aria-hidden", "true");
    });

    surpriseOverlay?.addEventListener("click", (event) => {
      if (event.target === surpriseOverlay) {
        surpriseOverlay.classList.remove("is-visible");
        surpriseOverlay.setAttribute("aria-hidden", "true");
      }
    });
  }

  function setupCards() {
    $$("[data-card]").forEach((card) => {
      const button = $("[data-card-button]", card);
      button?.addEventListener("click", () => {
        card.classList.toggle("is-open");
        card.classList.add("is-pressed");
        emitConfetti(button, { count: 20, spread: 95 });
        window.setTimeout(() => card.classList.remove("is-pressed"), 180);
      });
    });
  }

  function openLightbox(trigger) {
    const src = trigger.dataset.lightboxSrc;
    const caption = trigger.dataset.lightboxCaption || "A sweet memory with Shruti";
    if (!src || !lightboxDialog || !lightboxImage || !lightboxCaption) return;

    lightboxCaption.textContent = caption;
    lightboxImage.alt = caption;

    const showLightbox = (resolvedSrc) => {
      lightboxImage.hidden = false;
      lightboxImage.src = resolvedSrc;
      if (typeof lightboxDialog.showModal === "function") {
        lightboxDialog.showModal();
      } else {
        lightboxDialog.setAttribute("open", "");
      }
    };

    const probe = new Image();
    probe.onload = () => {
      showLightbox(src);
    };
    probe.onerror = () => {
      const embeddedSrc = EMBEDDED_PHOTOS[src];
      if (embeddedSrc) {
        showLightbox(embeddedSrc);
      } else {
        lightboxImage.hidden = true;
        lightboxImage.removeAttribute("src");
        lightboxImage.alt = "Photo preview is waiting for the supplied image file.";
        lightboxCaption.textContent = "This memory is ready for the real photo at " + src + ".";
        if (typeof lightboxDialog.showModal === "function") {
          lightboxDialog.showModal();
        } else {
          lightboxDialog.setAttribute("open", "");
        }
      }
    };
    probe.src = src;
  }

  function setupLightbox() {
    $$("[data-lightbox-src]").forEach((trigger) => {
      trigger.addEventListener("click", () => openLightbox(trigger));
    });
  }

  function setupRakhi() {
    const tieButton = $("#tieRakhi");
    const rakhi = $("#interactiveRakhi");
    const status = $("#rakhiStatus");
    if (!tieButton || !rakhi || !status) return;

    tieButton.addEventListener("click", () => {
      rakhi.classList.remove("is-tied");
      void rakhi.offsetWidth;
      rakhi.classList.add("is-tied");
      status.innerHTML = "Bond officially renewed â¤<br><span>Forever brother &amp; sister.</span>";
      emitConfetti(tieButton, { count: 56, spread: 160, symbols: ["â¤", "â™¡", "âœ¦", "ðŸª¢"] });
    });
  }

  function setupSecret() {
    const unlockButton = $("#unlockSecret");
    unlockButton?.addEventListener("click", () => {
      emitConfetti(unlockButton, { count: 36, spread: 120 });
      if (typeof secretDialog?.showModal === "function") {
        secretDialog.showModal();
      } else {
        secretDialog?.setAttribute("open", "");
      }
    });
  }

  function setupDialogs() {
    $$("[data-close-dialog]").forEach((button) => {
      button.addEventListener("click", () => {
        const dialog = button.closest("dialog");
        if (!dialog) return;
        if (typeof dialog.close === "function") {
          dialog.close();
        } else {
          dialog.removeAttribute("open");
        }
      });
    });

    $$("dialog").forEach((dialog) => {
      dialog.addEventListener("click", (event) => {
        if (event.target === dialog) {
          if (typeof dialog.close === "function") dialog.close();
          else dialog.removeAttribute("open");
        }
      });
    });

    document.addEventListener("keydown", (event) => {
      if (event.key !== "Escape") return;
      if (surpriseOverlay?.classList.contains("is-visible")) {
        surpriseOverlay.classList.remove("is-visible");
        surpriseOverlay.setAttribute("aria-hidden", "true");
      }
      header?.classList.remove("nav-open");
      navToggle?.setAttribute("aria-expanded", "false");
    });
  }

  initializeImages();
  revealOnScroll();
  setupNavigation();
  setupBackToTop();
  setupSurpriseButtons();
  setupCards();
  setupLightbox();
  setupRakhi();
  setupSecret();
  setupDialogs();
})();
